import { useState, useEffect, useContext } from "react";
import api from "../api"; // Axios instance with baseURL and token
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";
import { Dialog } from "@headlessui/react";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");
  const [candidateModalOpen, setCandidateModalOpen] = useState(false);
  const [candidateForm, setCandidateForm] = useState({ id: null, name: "", position: "", party: "" });
  const { logout } = useContext(AuthContext);
  const navigate = useNavigate();

  // Fetch initial data
  useEffect(() => {
    fetchVotingState();
    fetchPendingUsers();
    fetchCandidates();
    fetchLogs();
  }, []);

  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      alert("Failed to fetch voting state: " + (err.response?.data?.error || err.message));
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data.pendingUsers || []);
    } catch (err) {
      alert("Failed to fetch pending users: " + (err.response?.data?.error || err.message));
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data.candidates || []);
    } catch (err) {
      alert("Failed to fetch candidates: " + (err.response?.data?.error || err.message));
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data.logs || []);
    } catch (err) {
      alert("Failed to fetch logs: " + (err.response?.data?.error || err.message));
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting", { votingOpen: !votingOpen });
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      alert("Failed to toggle voting: " + (err.response?.data?.error || err.message));
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      alert("Failed to approve user: " + (err.response?.data?.error || err.message));
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      alert("Failed to reject user: " + (err.response?.data?.error || err.message));
    }
  };

  const openCandidateModal = (candidate = null) => {
    if (candidate) setCandidateForm(candidate);
    else setCandidateForm({ id: null, name: "", position: "", party: "" });
    setCandidateModalOpen(true);
  };

  const handleCandidateSubmit = async () => {
    try {
      if (candidateForm.id) {
        await api.put(`/admin/candidates/${candidateForm.id}`, candidateForm);
      } else {
        await api.post("/admin/candidates", candidateForm);
      }
      fetchCandidates();
      setCandidateModalOpen(false);
    } catch (err) {
      alert("Failed to save candidate: " + (err.response?.data?.error || err.message));
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Are you sure you want to delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      alert("Failed to delete candidate: " + (err.response?.data?.error || err.message));
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.report ? JSON.stringify(res.data.report) : "");
    } catch (err) {
      alert("Failed to generate report: " + (err.response?.data?.error || err.message));
    }
  };

  return (
    <div className="min-h-screen bg-gray-100">
      {/* Header */}
      <header className="bg-white shadow-md py-4 px-6 flex justify-between items-center">
        <h1 className="text-2xl font-bold text-gray-800">iVote Admin Dashboard</h1>
        <button
          onClick={() => { logout(); navigate("/login"); }}
          className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
        >
          Logout
        </button>
      </header>

      <main className="p-6 space-y-6">
        {/* Voting Control */}
        <section className="bg-white p-6 rounded-xl shadow-md flex justify-between items-center">
          <div>
            <h2 className="text-xl font-semibold text-gray-800">Voting Status</h2>
            <p className="text-gray-600 mt-1">
              Current Status:{" "}
              <span className={votingOpen ? "text-green-600" : "text-red-600"}>
                {votingOpen ? "Open" : "Closed"}
              </span>
            </p>
          </div>
          <button
            onClick={toggleVoting}
            className={`px-6 py-3 rounded-lg font-semibold text-white ${
              votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"
            }`}
          >
            {votingOpen ? "Close Voting" : "Open Voting"}
          </button>
        </section>

        {/* Pending Users */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">Pending Voter Registrations</h2>
          {pendingUsers.length === 0 ? (
            <p className="text-gray-500">No pending users.</p>
          ) : (
            <table className="w-full table-auto border-collapse border border-gray-200">
              <thead>
                <tr className="bg-gray-100">
                  <th className="border px-4 py-2">Student Number</th>
                  <th className="border px-4 py-2">Name</th>
                  <th className="border px-4 py-2">Email</th>
                  <th className="border px-4 py-2">Actions</th>
                </tr>
              </thead>
              <tbody>
                {pendingUsers.map((user) => (
                  <tr key={user.id}>
                    <td className="border px-4 py-2">{user.studentNumber}</td>
                    <td className="border px-4 py-2">{user.name}</td>
                    <td className="border px-4 py-2">{user.email}</td>
                    <td className="border px-4 py-2 space-x-2">
                      <button
                        onClick={() => approveUser(user.id)}
                        className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700"
                      >
                        Approve
                      </button>
                      <button
                        onClick={() => rejectUser(user.id)}
                        className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700"
                      >
                        Reject
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>

        {/* Candidates Management */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">Candidates</h2>
          <table className="w-full table-auto border-collapse border border-gray-200">
            <thead>
              <tr className="bg-gray-100">
                <th className="border px-4 py-2">Name</th>
                <th className="border px-4 py-2">Position</th>
                <th className="border px-4 py-2">Party</th>
                <th className="border px-4 py-2">Actions</th>
              </tr>
            </thead>
            <tbody>
              {candidates.map((c) => (
                <tr key={c.id}>
                  <td className="border px-4 py-2">{c.name}</td>
                  <td className="border px-4 py-2">{c.position}</td>
                  <td className="border px-4 py-2">{c.party || "-"}</td>
                  <td className="border px-4 py-2 space-x-2">
                    <button
                      onClick={() => openCandidateModal(c)}
                      className="bg-blue-600 text-white px-3 py-1 rounded hover:bg-blue-700"
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => deleteCandidate(c.id)}
                      className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          <button
            onClick={() => openCandidateModal()}
            className="mt-4 bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
          >
            Add Candidate
          </button>
        </section>

        {/* Candidate Modal */}
        <Dialog
          open={candidateModalOpen}
          onClose={() => setCandidateModalOpen(false)}
          className="relative z-50"
        >
          <div className="fixed inset-0 bg-black/30 flex items-center justify-center">
            <div className="bg-white p-6 rounded shadow-lg max-w-sm w-full">
              <Dialog.Title className="text-lg font-bold mb-2">
                {candidateForm.id ? "Edit Candidate" : "Add Candidate"}
              </Dialog.Title>
              <div className="flex flex-col gap-3">
                <input
                  placeholder="Name"
                  value={candidateForm.name}
                  onChange={(e) => setCandidateForm({ ...candidateForm, name: e.target.value })}
                  className="border rounded px-3 py-2"
                />
                <input
                  placeholder="Position"
                  value={candidateForm.position}
                  onChange={(e) => setCandidateForm({ ...candidateForm, position: e.target.value })}
                  className="border rounded px-3 py-2"
                />
                <input
                  placeholder="Party"
                  value={candidateForm.party}
                  onChange={(e) => setCandidateForm({ ...candidateForm, party: e.target.value })}
                  className="border rounded px-3 py-2"
                />
              </div>
              <div className="mt-4 flex justify-end gap-2">
                <button
                  onClick={() => setCandidateModalOpen(false)}
                  className="px-4 py-2 bg-gray-300 rounded"
                >
                  Cancel
                </button>
                <button
                  onClick={handleCandidateSubmit}
                  className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
                >
                  {candidateForm.id ? "Save Changes" : "Add Candidate"}
                </button>
              </div>
            </div>
          </div>
        </Dialog>

        {/* System Logs */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-xl font-semibold text-gray-800 mb-4">System Logs</h2>
          {logs.length === 0 ? (
            <p className="text-gray-500">No logs available.</p>
          ) : (
            <ul className="space-y-2 max-h-64 overflow-y-auto">
              {logs.map((log) => (
                <li key={log.id} className="text-gray-700">
                  {log.message} <span className="text-gray-400 text-sm">{log.timestamp}</span>
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* Reports */}
        <section className="bg-white p-6 rounded-xl shadow-md flex flex-col items-start space-y-3">
          <h2 className="text-xl font-semibold text-gray-800">Reports</h2>
          <button
            onClick={generateReport}
            className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700"
          >
            Generate Final Report
          </button>
          {reportHash && (
                        <pre className="text-gray-600 mt-2 p-2 bg-gray-100 rounded w-full overflow-x-auto">
                        {reportHash}
                      </pre>
                    )}
                  </section>
                </main>
              </div>
            );
          }
